UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My call to the office was a stressed out mother needing advice for one of her children. I was lucky enough to be connected with Michael Spratt who quickly calmed me down and told me exactly what I needed to do. A huge thank you Michael for your help and understanding.","author":"Caroline V.","url":"https://www.agpllp.ca/"}]')), updated_at = datetime('now') WHERE slug = 'agp-llp-ottawa-criminal-lawyers-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Quick, efficient and professional. Worked to get me out of a charge that would have ruined my life. I would highly recommend them. Can be pricey but worth it for peace of mind. Thank you Edmund Chan for your effort.","author":"","url":"https://fightthecharges.com/kingston-criminal-lawyers/"},{"text":"I loved dealing with Aitken, The lawyers were very professional, they assisted me with my charges and provided a generally positive outcome. I really couldn’t have asked for a better outcome The firm also assisted me with setting a solid payment plan that I''m able to manage and improve on. Thank you!","author":"","url":"https://fightthecharges.com/kingston-criminal-lawyers/"},{"text":"They are the best, Edmund and his crew got me off some bogus charge, I''m grateful and they were very professional. Would recommend to anyone. Best spent money","author":"","url":"https://fightthecharges.com/kingston-criminal-lawyers/"}]')), updated_at = datetime('now') WHERE slug = 'aitken-robertson-kingston' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Real down to earth guy. He took my call on short notice, was able to point me in the right direction. Sat there and took the time to hear me out , asked me lots of questions. Very dedicated to detail . I dont make much money and yet he took the time to help me out.","author":"","url":"https://fightthecharges.com/peterborough-impaired-driving/"},{"text":"Spoke with Mr. Aiken Robertson about the matter on hand. Was very professional with the matter I’m dealing with.","author":"","url":"https://fightthecharges.com/peterborough-impaired-driving/"},{"text":"How many people can say they had a GREAT experience with a criminal attorney? Well, long story short, I can. When things hit the fan they were there right away, allowed texting, phone calls within 5 minutes and a complete early strategy that kept me safe during a crazy time.","author":"","url":"https://fightthecharges.com/peterborough-impaired-driving/"}]')), updated_at = datetime('now') WHERE slug = 'aitken-robertson-peterborough' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Greetings Shabnam, my wife just got her open work visa and is on the job hunt. Thanks for your quick and speedy turn around. You guys made this a breeze.","author":"","url":"https://thevisa.ca/"},{"text":"My thanks to you and your team, Shabnam. My wife and I have just entered Canada and received our documents. I am now a Federal Skilled Worker ;) We couldn’t have done this without you.","author":"","url":"https://thevisa.ca/"},{"text":"Thank you for reuniting me with my wife, I thought this day would never come. I do not know why Canada gave us such a hard time, wish I came to you first. Now she has her PR and we can resume our normal lives together. You have made our dreams come true.","author":"","url":"https://thevisa.ca/"}]')), updated_at = datetime('now') WHERE slug = 'akrami-and-associates-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"One of my good friends referred me to Alice Huynh''s law firm and I''m very grateful and happy to have found such an amazing and attentive lawyer. I''m newly divorced and she made the process simple and easy for me. Something that made me very anxious, anyone going through a divorce would know exactly what I''m talking about.","author":"","url":"https://alicehuynhlaw.com/en/"},{"text":"I am so glad I found Alice as a lawyer that specializes in family law for my dad. My dad does not know how to speak english well, so the fact that Alice can speak Vietnamese fluently to my dad was a huge plus! It took away a lot of information that can be loss through translation.","author":"","url":"https://alicehuynhlaw.com/en/"},{"text":"[I] very much appreciated having Alice as my lawyer. The attribute that impressed me the most was her integrity. She was sympathetic about the unfairness of my case but none the less stuck to her professional opinion... She could have easily strung me along and sent me a big bill in the end.","author":"","url":"https://alicehuynhlaw.com/en/"}]')), updated_at = datetime('now') WHERE slug = 'alice-huynh-law-corporation-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Joanne is the best person I could have asked for to work through our cohabitation agreement with. Professional, kind, easy to speak to and throughout the process I always felt well informed.” Linstead P.","author":"","url":"https://alignfamilylaw.ca/testimonials/"},{"text":"At a very difficult time in my life, Joanne and her team at Align Family Law have been compassionate, articulate, very knowledgeable, and we even managed to share some laughs! She made a very painful process as painless as possible.” Tracey T.","author":"","url":"https://alignfamilylaw.ca/testimonials/"},{"text":"Joanne was great. I think her resolution seeking approach is a fantastic way to find solutions to these difficult issues. The guidance and advice from Joanne was spot on.” Dave C.","author":"","url":"https://alignfamilylaw.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'align-family-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"What a pleasure working with Scott Duncan was. He was very efficient and at the same time very thorough. I expressed what I was looking to get out of the lawyer process and he greatly exceeded my expectations. I would recommend Scott to anyone looking to recoup any damages they feel that they incurred.","author":"","url":"https://alloy.law/"},{"text":"Joe Iwanicki took my case on and immediately made me feel confident with an intelligent approach combined with a confident demeanour. Together, we fought what seemed like a hopeless fight for three years against a much larger party with limitless funds and resources.","author":"","url":"https://alloy.law/"},{"text":"Greg helped us close the transaction on our first rental property. He was prompt and prepared. Any questions we had were answered thoroughly and he communicated throughout the whole process. We look forward to working with him to acquire new properties.","author":"","url":"https://alloy.law/"}]')), updated_at = datetime('now') WHERE slug = 'alloy-llp-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I have had the pleasure of working with the team at Sidhu & Associates for over 6 years now. They have handled thousands of files for us. Jimmy, Kiran, and Ashley are friendly, professional, and just an absolute joy to deal with. They are highly knowledgeable and very quick/efficient in their process. I highly recommend their services.","author":"","url":"https://ambassadorlaw.ca/"},{"text":"Sidhu and Associates is our go-to legal firm for all out clients. I''ve had the privilege of working with Terry Sidhu/Jimmy Kumar and their dedicated team for our 20 years handling over 1000 files together. Their staff is always friendly, providing a warm welcome, and they are incredibly efficient and thorough in their work.","author":"","url":"https://ambassadorlaw.ca/"},{"text":"I have confidently referred clients to Terry & his staff for over 20 years. Very professional, very prompt & very knowledgeable. Terry has always made himself available to answer my questions.","author":"","url":"https://ambassadorlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ambassador-law-corporation-abbotsford' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
