UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I was very satisfied with the outcome.      \"Ahmad, thank you for representing me....I was very satisfied with the outcome....thank you\" Frank Zimmer Chatham, Ontario","author":"","url":"https://www.ammarlaw.ca/"},{"text":"Thank you for your help when I needed it most.      \"The representation was excellent. I felt like I was a friend and family member throughout my legal matter. We were successful in trial and I was found not guilty on 15 counts.","author":"","url":"https://www.ammarlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ammar-law-professional-corporation-windsor' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I recently worked with Derek and his team, and I couldn’t be more impressed! Their professionalism, expertise, and communication skills made the entire process seamless and stress-free. Their attention to detail and prompt responses to my queries were particularly noteworthy. I highly recommend their services to anyone seeking reliable and personalized support.","author":"","url":"https://anglawpc.com/"},{"text":"I’ve had multiple positive experiences with Derek, where he had helped draft the wills for me and my family members, power of attorney for property and personal care, and closing the purchase and sale of multiple properties. Derek behaves professionally, is particularly knowledgeable in real estate law, and has been very responsive throughout each of my interactions with him.","author":"","url":"https://anglawpc.com/"},{"text":"I had the pleasure of working with Derek from Ang Law to draft a will for my family, and I couldn’t be more satisfied with the service he provided. From the very beginning, Derek was professional, patient, and incredibly knowledgeable.","author":"","url":"https://anglawpc.com/"}]')), updated_at = datetime('now') WHERE slug = 'ang-law-professional-corporation-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My experience with Anita perera was fantastic. She was so humble and understood everything perfectly. I recommend everyone if have any notarized work visit her.","author":"ANKITJOT K.","url":"https://anitapereralaw.ca/"},{"text":"I was extremely pleased with the service provided at Anita Perera Law. They closed the sale of my condo in a very smooth manner. Never did I feel rushed or pressured when providing documentation and everything was finalized well before the closing day. I was also treated with kindness and respect by Anita, Dewmini, and the receptionist. 5 stars.","author":"Red","url":"https://anitapereralaw.ca/"},{"text":"Anita is helpful and compassionate. I was able to move quickly and efficiently throughout this unexpected turn of events with Anita by my side.","author":"Shirley D.","url":"https://anitapereralaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'anita-perera-law-professional-corp-lawyers-and-notary-public-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"She''s very thorough and very compassionate. She walked me through everything so smoothly and efficiently and answered everything fully ! This law firm is the best to go to if you want someone empathetic , honest and supportive .","author":"","url":"https://ansarilaw.ca/"},{"text":"Honest, useful first consult. Clear on what is and isn’t realistic for me and took the time to understand my situation. No pressure. Highly recommend.","author":"","url":"https://ansarilaw.ca/"},{"text":"We had a great experience with Yameena and team. The Canadian immigration system is complex and difficult and only growing moreso lately, yet she was able to help us systematically navigate the options. Highly reccomend.","author":"","url":"https://ansarilaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ansari-immigration-law-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
