UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Choosing Bergel Magence was the smartest decision my wife and I could have made during the most frightening and confusing time in my life. I sustained a traumatic brain injury from a car accident. Andrew Bergel immediately saw to my rehabilitation by putting together an excellent team of doctors, support workers and therapists.","author":"","url":"https://www.bergellaw.com/resources/testimonials/"},{"text":"I changed from another law firm to Bergel Magence LLP because I was dissatisfied with my first lawyer’s lack of personal attention to my soft tissue injury claim. The lawyer at Bergel Magence LLP focused on my claim, provided me with personal attention and negotiated a settlement of $225,000 less than one year after I changed lawyers. P.G.","author":"","url":"https://www.bergellaw.com/resources/testimonials/"},{"text":"In 2005, I was involved in a serious car accident which left me unable to work. Initially, I tried to deal with the insurance claims on my own, but when the insurance company continued to deny my benefits, I felt helpless, frustrated and in need of income replacement to support my family.","author":"","url":"https://www.bergellaw.com/resources/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'bergel-magence-guelph' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I suffered a traumatic accident back in 2015 and I had Ron Preyra help me since the very beginning. He showed compassion from day one and has always given me the best advice possible. He also surprised me by returning my emails very promptly, letting me know that I was a valuable client for his practice.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"},{"text":"I have known Mr Preyra for over 17 yrs and he has represented me on several occasions. He is dedicated, assertive, professional, and realistic. I will recommend Alan as a Lawyer to any one who requires legal assistance in any capacity. Continue in excellence Alan.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"},{"text":"I was very pleased with the professional service and dedicated attention I received through working with Alan C. Preyra. I felt, at all times, that Alan was serving my best interests. Mr. Preyra is a strong advocate, and his unwavering goal of ensuring my case was fairly tried, lessened my emotional burden. I would recommend Mr.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'bergmanis-preyra-llp-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
