UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Rick was very nice to work with. He was very patient and always explained everything in a way we could understand. I would recommend Rick to all my friends and family.","author":"","url":"https://bickhramlitigation.com/"},{"text":"Rick was recommended to us by another lawyer and I’m glad we decided to have him represent our family member in her legal proceedings. I was impressed by his commitment to his client, knowledge, and professionalism, as well as with his patience in answering endless questions in a way we could understand.","author":"","url":"https://bickhramlitigation.com/reviews-2"},{"text":"I was referred by another estate lawyer who had worked with Rick and had nothing but praise for his talent. I wasn’t disappointed, Rick got the job done and listened to my concerns throughout the entire process. I highly recommend him.","author":"","url":"https://bickhramlitigation.com/reviews-2"}]')), updated_at = datetime('now') WHERE slug = 'bickhram-litigation-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
