UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Our experience with Cunningham Swan has not only satisfied our needs, it has expanded our capacities as an organization. Expertise has been brought to address every facet of our work with clarity and diligence. Our goals have grown through hard work and the creative initiatives of Lisa (lawyer) who work(s) with us as colleagues.","author":"","url":"https://cswan.com/"},{"text":"I have worked with Cunningham Swan’s corporate law group for 7 years now. In addition to donating their own personal volunteer time, they provide the pro-bono legal work for the local Kingston Kids Triathlon.","author":"","url":"https://cswan.com/"},{"text":"I was lucky enough to have Andrew represent me through a business sale. He made sure I understood all of the policies and procedures as well as checked in to make sure I was doing okay, He was not only knowledgeable, but compassionate and caring towards me and my family during a difficult time.","author":"","url":"https://cswan.com/"}]')), updated_at = datetime('now') WHERE slug = 'cunningham-swan-carty-little-bonham-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
