UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My husband and i recently bought and sold a house. The staff at TLR helped us with process in a timely matter. We were very happy with the service that they provided.","author":"","url":"https://tlrlaw.ca/"},{"text":"COVID project was to update our wills and put in place POAs.... they were responsive to our needs, did most transactions by teleconference. Whole process took less than a month....from first inquiry to receipt of notarized copies. Thanks.","author":"","url":"https://tlrlaw.ca/"},{"text":"Very professional service. I would recommend them to anyone looking for a will and power of attorney. I just had both done and feel so good about it.","author":"","url":"https://tlrlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'etude-davocats-tlr-law-office-winnipeg' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Stephen and his team went above and beyond representing my interests. Not only was my case represented but Stephen talked me through the process which allowed me to be patient. The team stood strong and finished the fight. I am grateful for their representation","author":"Leather B.","url":"https://evolutionlegal.ca/"},{"text":"I researched several employment lawyers before reaching out to Stephen and I’m so glad I followed my intuition. From our first conversation, he was professional, knowledgeable, helpful, compassionate, and genuinely reassuring.","author":"Ashlee C.","url":"https://evolutionlegal.ca/"},{"text":"&lt;strong&gt;Outstanding support and expertise&lt;/strong&gt; Stephen provided exceptional guidance and support during a very difficult time. His approachable nature instantly made me feel comfortable, and he consistently kept me updated with honest and practical advice. His dedication and expertise were evident throughout the process, ultimately leading to a great resolution.","author":"Suzanne","url":"https://evolutionlegal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'evolution-legal-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
