UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Jennifer Gold and her staff are absolutely amazing!!. I cannot say enough good things about them. They helped my mother with a very sensitive case. They were patient, empathetic and professional. Truly a God sent. They stuck by her through the entire process and lead her to a victory! Thank you Jennifer and your entire team!! God bless.","author":"","url":"https://goldfamilylaw.ca/"},{"text":"Thank you Jennifer Gold for your professionalism and excellent guidance - you are a powerful lawyer with wonderful decorum, advice and many other factors. Parthena Nikoletsos what a phenomenal , talented, capable, incredible asset you are to Wood Gold. I cannot thank you enough for your constant support and assistance ...","author":"","url":"https://goldfamilylaw.ca/"},{"text":"Thank you to Andrea Dunsmuir who helped me with my legal matter. It went very smoothly and efficiently.","author":"","url":"https://goldfamilylaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'gold-family-law-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Ian has been my immigration lawyer for close to ten years now. Throughout that time, he and his team have... Ian has been my immigration lawyer for close to ten years now.","author":"","url":"https://immigrationtocanada.org/"},{"text":"Ian is very knowledgeable. We had done quite a bit of internet research and thought we were well-prepared but Ian... Ian is very knowledgeable. We had done quite a bit of internet research and thought we were well-prepared but Ian was able to clear up a couple of misconceptions and provide additional highly useful information.","author":"","url":"https://immigrationtocanada.org/"},{"text":"I couldn''t be happier with the immigration services I received. From our very first meeting, it was clear this team... I couldn''t be happier with the immigration services I received.","author":"","url":"https://immigrationtocanada.org/"}]')), updated_at = datetime('now') WHERE slug = 'goldman-associates' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had an excellent experience working with Tushaar and Raman. From the very beginning, they demonstrated a high level of professionalism, knowledge, and genuine care for their clients. What really stood out was how responsive they were—calls and emails were always returned promptly, and I never felt left waiting or uncertain about the status of my matter.","author":"","url":"https://goldwynlaw.ca/"},{"text":"The team did an amazing job on closing of my condo The Goldwyn team is highly recommended","author":"","url":"https://goldwynlaw.ca/"},{"text":"My husband and I worked with this firm for the legal process of purchasing our home, and our lawyer was excellent. The entire experience was smooth, seamless, and very well organized. They answered all our questions, were always reachable, and guided us clearly through every step.","author":"","url":"https://goldwynlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'goldwyn-law-professional-corporation-markham' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"As a multinational corporation, we as an employer in Canada value efficiency and reliability. GOOSELAW™ immigration law firm has consistently delivered on both fronts. Their fast and secure online service streamlines the work permit application process, and we’ve experienced a close to 100% success rate with their expert guidance and excellent services to date.","author":"","url":"https://gooselaw.com/reviews/"},{"text":"Having been at our wits end having faced obstacle after obstacle in completing the requirements for an LMIA application for our firm, we reached out to GOOSELAW Immigration law firm. Donovan was extremely professional and gave us excellent advice.","author":"","url":"https://gooselaw.com/reviews/"},{"text":"Our experience with GOOSELAW Immigration law firm has been instrumental in securing work authorization in Canada. Getting our work visa approved was a long, complicated process but the GOOSELAW Immigration team was amazing!","author":"","url":"https://gooselaw.com/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'gooselaw-immigration-law-firm-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"For the past 18 months, I have been providing support to a friend of mine with major accidental issues, whom has been working with Mr. Gosal and his team of experts at Gosal & Company law firm. I would like to offer my sincere gratitude for all the effort and patience they have shown and offered to my friend.","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"},{"text":"After years of negotiating, Gosal & Company was successful in settling my claim for my full disability compensation. Thanks to Sarj Gosal, Michelle Bissenden and the rest of the team for all your hard work so I didn''t have to deal with all the headaches that come with dealing with Worksafe. I highly recommend Gosal & Company to represent you.","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"},{"text":"Thank you Gosal & Company for all your help with my WCB claim as well as my CPP file. I couldn’t have done it successfully without your expertise, and hard work. Much appreciated. I highly recommend Gosal & Company.","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"}]')), updated_at = datetime('now') WHERE slug = 'gosal-and-company-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"George is an exceptional criminal lawyer whose dedication and expertise exceeded all expectations … His courtroom presence is truly remarkable — confident, persuasive, and commanding. He fought tirelessly on our behalf and had our case dismissed. If you''re seeking a top-tier criminal lawyer, look no further than George.","author":"","url":"https://georgegray.ca/testimonials/"},{"text":"Facing a criminal charge for the first time was overwhelming and scary, especially knowing I was innocent. George guided me through every step with confidence and care, and thanks to his dedication and expertise, my charges were completely withdrawn before trial. I truly couldn''t have asked for a better outcome or a better lawyer.","author":"","url":"https://georgegray.ca/testimonials/"},{"text":"As someone who had no idea how the system works, George helped me out and did an exceptional job with my case, which was withdrawn. I''m grateful for your help. I highly recommend him if you need someone who can help you with any case.","author":"","url":"https://georgegray.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'gray-criminal-defence-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had an outstanding experience working with Green and Spiegel on my visa application. From the very beginning, their team, especially Cristina Guida and Lysandra Deschenes, provided exceptional support. I was truly impressed by how fast the entire process was handled. They were incredibly organized, efficient, and knowledgeable, making sure that every detail was addressed.","author":"","url":"https://gands.com/about-us/our-reputation/"},{"text":"We were looking for an Immigration Law firm to help us with our immigration needs. I found Green and Spiegel on google and based on their google reviews I decided to partner with them. The decision to go with them was absolutely fruitful. Under the able leadership of Jonathan Green, we were able to successfully achieve all our immigration needs.","author":"","url":"https://gands.com/about-us/our-reputation/"}]')), updated_at = datetime('now') WHERE slug = 'green-and-spiegel-llp-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"The people at Grover Law Firm were awesome in helping me getting my settlement. Miss Summer Abbasi and Steve Grover were professional in helping me.","author":"","url":"https://www.groverlawfirm.com/"},{"text":"Grover Law firm has exceptional service. Went above and beyond. Very easy to work with and empathetic to my situation. The outcome was more than expected. I would highly recommend to anyone needing an injury lawyer.","author":"","url":"https://www.groverlawfirm.com/"},{"text":"There’s not enough words to express the gratitude I have for the professionalism, guidance, and support while the team at Grover worked diligently to get my case settled. Olukemi Daniel-Ojo & her team made me feel seen, heard, valued and appreciated as a client from beginning to end during the challenging moments and really helped me to understand the process.","author":"","url":"https://www.groverlawfirm.com/"}]')), updated_at = datetime('now') WHERE slug = 'grover-law-firm-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Moving back to Alberta, we needed to redo our wills. Having met Shannon through the process we were blown away! This would be the third time we’ve updated wills, etc. in our lifetime. Shannon and her team are the most thorough and compassionate lawyers we’ve ever had the privilege to deal with.","author":"","url":"https://www.gunnlawgroup.ca/"},{"text":"Very helpful and professional explaining my case and getting through it all, I''m thankful for all there help in winning my case. highly recommend.","author":"","url":"https://www.gunnlawgroup.ca/"},{"text":"All of the lawyers were very professional, helpful, and accommodating with my son in assisting us through this difficult time. They were able to help us fill out all of the forms and documents we needed for our court case. They were patient with my son and guided us through everything we needed.","author":"","url":"https://www.gunnlawgroup.ca/"}]')), updated_at = datetime('now') WHERE slug = 'gunn-law-group-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am highly thankful to Gurna Law Corporation for getting me an approval for my post graduation open work permit. It was by no means a straightforward case. However, Mr. Saravpreet Singh and his team made the process very comfortable and easy for me. I would rank them very highly for their professionalism and care for my case.","author":"","url":"https://gurnalaw.ca/"},{"text":"I had an excellent experience with Sarvpreet and Gurna Law Corporation. Before him, I spoke with others who mishandled my case, making things worse. Sarvpreet took time to understand, guided me clearly, and helped streamline my case. His responses were quick, professional, and helpful. Following his advice, I received my permanent residency.","author":"","url":"https://gurnalaw.ca/"},{"text":"Today my Open Work Permit was approved, and I am incredibly relieved. I was in a very difficult and vulnerable situation, filled with fear and uncertainty about my future. Gurna Law Corporation worked tirelessly on my case and supported me every step of the way.","author":"","url":"https://gurnalaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'gurna-law-corporation-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had the great pleasure of working with Ainsley and Zoe. They were both professional, compassionate, attentive, kind and very supportive for my case. Thank you for bringing forth ease to such a stressful situation. I cannot find the words to express my gratitude in helping me through this process.","author":"","url":"https://hammerco.ca/our-firm/testimonials-and-results/"},{"text":"I turned my pain and suffering into something great. I was able to use some of the settlement to do lots of healing and set up my own practice to offer services to others and it''s going well. So it''s been a story of transformation as far as I''m concerned.","author":"","url":"https://hammerco.ca/our-firm/testimonials-and-results/"},{"text":"I can’t recommend Morgyn and her team highly enough to anyone dealing with an MVA. Throughout the entire negotiation process with ICBC, I felt 100% supported and confident in the outcome, which allowed me to fully focus on my recovery.","author":"","url":"https://hammerco.ca/our-firm/testimonials-and-results/"}]')), updated_at = datetime('now') WHERE slug = 'hammerco-lawyers-llp-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Handa Law is one of the reliable and professional law firm we have ever dealt with. Happy with their consultation.","author":"","url":"https://www.handalawpc.ca/"},{"text":"I needed to get the custody of my child and Handa Law helped me with it. Thankfully my child is with me now. Highly recommend their service.","author":"","url":"https://www.handalawpc.ca/"},{"text":"Would highly recommend Handa Law ! Very professional and respectful lawyer ! She is super resourceful with her work. Definitely would trust her with my issues/work.","author":"","url":"https://www.handalawpc.ca/"}]')), updated_at = datetime('now') WHERE slug = 'handa-law-professional-corporation-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Outstanding work and professionalism. Sukhi is an extremely knowledgable lawyer and is committed to getting the best possible outcome for his clients. He is efficient, personable and easy to work with, and he genuinely cares about his clients’ success - a rare quality to find in a lawyer.","author":"","url":"https://www.hansralaw.ca/about-business-law-firm/testimonials/"},{"text":"Sukhi Hansra is a very professional, knowledgable lawyer and a man of his word. Whether it involved the review of legal documents or incorporating a small business in Ontario, Sukhi''s communication skills and patience made the entire process a seamless and enjoyable one.","author":"","url":"https://www.hansralaw.ca/about-business-law-firm/testimonials/"},{"text":"Sukhi has a motto of caring about the business and providing massive value, ex: works through the business plan, connects accountant with what''s needed, gives follow up calls. He''s also really knowledgeable in both business and tech which is a huge plus. I''ve dealt with many lawyers and this is an extraordinary commitment to great service.","author":"","url":"https://www.hansralaw.ca/about-business-law-firm/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'hansra-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Brad and his team are efficient, friendly and knowledgeable. I cannot recommend them highly enough","author":"","url":"https://haraco.ca/"},{"text":"Very professional law firm at reasonable pricing...and very timely service. Zach Pringle (an associate there) is awesome. I now use them exclusively for all my clients mortgage needs.","author":"","url":"https://haraco.ca/"},{"text":"I have used Brad Hara for over 13 years and he has never let me down. His services is always top notch and I trust him will all of my Real Estate Clients.","author":"","url":"https://haraco.ca/"}]')), updated_at = datetime('now') WHERE slug = 'hara-company' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"First time here. The Lawyer is a real gentleman. Very professional and gives the right advice. He was very nice and gave us all the time we needed, and answered all our questions knowledgeably. And the office staff are all kind and welcoming. Highly recommended.","author":"","url":"https://harrislawniagara.ca/testimonials"},{"text":"I have used Ken Harris several times and I have always been happy with their services. Ken is friendly, helpful and takes the time to explain everything in layman''s terms. I would recommend him and their office to any one.","author":"","url":"https://harrislawniagara.ca/testimonials"},{"text":"Mr. Harris and his staff are a pleasure to deal with. I highly recommend him for your real estate needs. We have used him over the last 15 yrs when buying property and have been completely satisfied each time.","author":"","url":"https://harrislawniagara.ca/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'harris-ramdowar-professional-corporation' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I would highly recommend Harsimran Makkar Law to anyone. Mr Makkar was very efficient, personable and to the point. He does not beat around the bush and will do anything in his power to help you in your situation. But always with consideration for where you stand, and what issues you are going through.","author":"","url":"https://www.hmakkarlaw.ca/testimonials/"},{"text":"Mr Harsimran Makkar is a highly qualified lawyer. He is very professional and handles sensitive issues with a lot of empathy. His response time is impeccable. His motto is to serve the client and not gouge them. He has been my counsel for a long time and has been very helpful in dealing with complicated issues.","author":"","url":"https://www.hmakkarlaw.ca/testimonials/"},{"text":"Given my current situation about my CEC entry, my PR application was refused. In all circumstances, I already depleted my savings. I came as an International student in Canada and have been living here for more than six years. I sought counsel to Mr.","author":"","url":"https://www.hmakkarlaw.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'harsimran-makkar-law-professional-corporation-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
