UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Ritu, you provided me with the guidance and knowledge for which I could never thank you enough. I think you’re amazing, compassionate, and knowledgeable; you’re definitely in the right profession.","author":"","url":"https://horrafamilylaw.com/"},{"text":"Reena Horra is a phenomenal lawyer, who exceeded my expectations on every level. I would wholeheartedly recommend her for any Family Law matter. Reena works very efficiently and achieves results without ever compromising your best interest or personal budget.","author":"","url":"https://horrafamilylaw.com/"},{"text":"Words cannot express how grateful I am to have had Ritu and Reena Horra represent me. Going through family matters is hard enough; you want to make sure you have people you can trust and rely on in your corner and that is exactly what I got with Horra Family Law.","author":"","url":"https://horrafamilylaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'horra-family-law-markham' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
