UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I was astounded at how well Pranav could not only help me with my legal issue, but in fact was cheaper than other firms I looked at. His attention to detail and customer service is inspiring. I highly recommend Khemka Law.","author":"F.B.","url":"https://khemkalaw.com/"},{"text":"We used the legal services of Khemka Law three times in the last year for real estate transactions. 2 of the 3 transactions had RPR (real property report) issues which Pranav was able to rectify. Pranav provides great customer service and conducts himself in a very professional manner.","author":"R.G.","url":"https://khemkalaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'khemka-law-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Stacy Cordeiro Kormans was fantastic to deal with for the closing of our home. They were knowledgeable, professional and very responsive. They made the process run as smoothly as possible. Heena was great and super responsive. They are professional and there service is amazing.i would definitely recommend them.","author":"","url":"https://www.kormans.ca/"},{"text":"Fariya F I had a good experience working with Jonathan and Reem from Kormans LLP. I had a very tight deadline to get a pre-construction review completed. Jonathan was quick to respond to my queries and Reem provided exceptional service within the short time-period. Highly recommended!","author":"","url":"https://www.kormans.ca/"},{"text":"Hasan Arshad I recently closed a Condo and used Kormans LLP’s services. Both Christina and Reem handled my case with great professionalism and care. They thoroughly guided me through the process and helped even with stuff like document pick up etc. Very responsive and efficient. Recommended!","author":"","url":"https://www.kormans.ca/"}]')), updated_at = datetime('now') WHERE slug = 'kormans-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I have had the pleasure of working with Jerry and his team on a number of Canadian immigration matters over the last two years. I have always found his guidance and counsel to be accurate, professional, timely, and easy to understand in the complex and ever changing world of immigration law.","author":"","url":"https://kreindlerlaw.com/testimonials/"},{"text":"Many thanks to you and your staff for all the work you did in preparing my application. Is at in the imigration waiting room at Toronto Airport waiting for them to process my application and had the opportunity to see what happens to individuals whose application was not as thoroughly prepared as mine was.","author":"","url":"https://kreindlerlaw.com/testimonials/"},{"text":"I successfully obtained my work permit this weekend. The Canadian immigration officers were happy with how the documents were put together and they wanted me to thank you both on doing such a fantastic job. They told me it was one of the best application packages they had ever seen and it made their job a lot easier.","author":"","url":"https://kreindlerlaw.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'kreindler-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We had a great experience with Kris! He is very professional and knowledgeable and walked us through the entire process. Highly recommend!","author":"","url":"https://kslawoffice.ca/"},{"text":"Kris is a great guy, very polite, patient, and knows his thing. My experience has been nothing less. Highly recommended.","author":"","url":"https://kslawoffice.ca/"},{"text":"Very knowledgeable, honest and delivers on time. I will always go back and will suggest his name to all I know.","author":"","url":"https://kslawoffice.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ks-law-professional-corporation-etobicoke' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I needed an employment lawyer to provide me some advices and I had a timeline to hit. When I emailed Jenson Leung, he replied within a few hours and was able to arrange a 30 min consultation with me promptly, even though he''s very busy.","author":"","url":"https://www.kswlawyers.ca/testimonials"},{"text":"Legal matters can be overwhelming, but working with Atty. Junki Hong has been an absolute blessing. He is a brilliant and knowledgeable advocate who clearly understands the law, but what I appreciate most is his human touch. He is genuinely kind, compassionate, and approachable.","author":"","url":"https://www.kswlawyers.ca/testimonials"},{"text":"I had a wonderful experience working with KSW Law Firm. Fiona and Mahum were incredibly professional, prompt and very helpful. I highly recommend KSW Law! Their team’s professionalism is incredible.","author":"","url":"https://www.kswlawyers.ca/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'ksw-lawyers' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"…The staff at all levels were pleasant, professional and supremely efficient in meeting our needs and responding to our legal queries. Chantal Lafreniere was at the helm, imparting clear and concise information while Lisa, Erica, Natalie and Kim were equally helpful in our transactions. Many thanks to you all!","author":"","url":"https://estatelawboutique.com/"},{"text":"My experience with Natalie Sanna, Lawyer of the Persona Law Group was comforting and certainly professional. From the moment I walked into the offices I was greeted promptly with kindness from the entire staff. Natalie spent time to listen treating all my concerns and information with respect.","author":"","url":"https://estatelawboutique.com/"},{"text":"Thank you very much for all your help, Lisa. I am very happy with how smoothly everything went, and I know that’s a testament to your firm’s professionalism and capability. Rest assured, if I have any future need for legal representation, I will be in touch.","author":"","url":"https://estatelawboutique.com/"}]')), updated_at = datetime('now') WHERE slug = 'lafreniere-sanna-estate-law-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Want to thank Sean for the very hard work he did on my case. He got me the best possible outcome and was honest with me right from the start. No sugar coating! He says he''s about being practical and thorough and that is exactly what he is. Thank you! D.K.","author":"","url":"https://ltllp.ca/"},{"text":"Sean was of great assistance to me and my family when I was in difficult times with my divorce and separation. Mr. Sean always had the patience to make me understand what is happening so I am less nervous when we go to court.","author":"","url":"https://ltllp.ca/"},{"text":"I retained Mr. Tram during a particularly gritty civil litigation dealing with the sale of my late father’s farm property. Mr. Tram was very patient with me as he explained to me the law as it interrelated with the different subsects of civil and estate litigation. Mr. Tram was a strong advocate for me both inside and outside the Court.","author":"","url":"https://ltllp.ca/"}]')), updated_at = datetime('now') WHERE slug = 'lakhan-tram-llp-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had the pleasure of meeting with Mr. Lalande. He was compassionate, honest, and straightforward. He made me feel comfortable and was supportive of my situation. I feel confident in his opinion and would not hesitate to recommend him and his lovely team.","author":"","url":"https://injured.ca/"},{"text":"Following a serious truck collision, I required extensive medical treatment for spinal cord damage. Their truck accident litigation experience was outstanding, and they fought relentlessly to achieve a fair settlement.","author":"","url":"https://injured.ca/"},{"text":"Matt Lalande and his team was recommended to me after I was injured in a serious head on collision. Throughout the entire process, I felt supported and as though they truly had my best interest at heart. It was easy to communicate and get the answers I needed to any questions I had throughout the process. Thank you Matt.","author":"","url":"https://injured.ca/"}]')), updated_at = datetime('now') WHERE slug = 'lalande-personal-injury-long-term-disability-lawyers' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I hired Lambert Law to represent me in my ICBC claim on the recommendation of my chiropractor. I had tendinitis in my shoulder from the collision which developed calcification, and as a result limited the use of my arm in a variety of ways.","author":"","url":"https://lambertlaw.com/client-reviews/"},{"text":"I was recommended to Lambert Law by my friend’s dad. I was involved in a motor vehicle collision in 2018 on the Malahat, when a driver heading the opposite direction fell asleep at the wheel and struck the vehicle beside me.","author":"","url":"https://lambertlaw.com/client-reviews/"},{"text":"Rory and his team have completed two real estate transactions for us in the last year (one on very short notice) and I have been super impressed with the service and support we have received. Their conveyancer, Sheri, is outstanding as well. We will be regulars in this office for life. Thank you! read more read less","author":"","url":"https://lambertlaw.com/client-reviews/"}]')), updated_at = datetime('now') WHERE slug = 'lambert-law-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Mr.Lamont and his team have been amazing. I owe him and his team my life. The treatment I received from the insurances has been appalling. I was treated like dirt by the insurance company despite all the Dr’s reports. I highly recommend Lamont Law firm to anyone dealing with accidents, insurance claims.","author":"","url":"https://lamontlaw.ca/"},{"text":"Dear Erica, Big, sincere THANK YOU – from the bottom of my heart! I’m so grateful for your amazing supports, help and – of course – winning the case! I wish you nothing but many beautiful moments in your professional and personal life! p.s. I’ll never forget what you have done for me!","author":"","url":"https://lamontlaw.ca/"},{"text":"I have nothing but positive and great things to say about the Lamont team. After being involved in a car accident... Erica Lamont took all of those worries away and replaced them with confidence that has enabled me to pursue my dreams and goals despite my accident. She is the perfect balance of professional and kind-hearted...","author":"","url":"https://lamontlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'lamont-law-hamilton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Professional service from the start to finish. Lisa and Ana were fantastic for us. Thanks for the legal support and drafting of our will.","author":"","url":"https://laredolaw.ca/"},{"text":"We recently worked with Lisa and her team to prepare wills and powers of attorney. It was a fantastic experience. Lisa is thorough, smart and I felt completely comfortable relying on her expertise and advice. She''s also a pleasure to chat with and really cares about her clients. I would highly recommend her services.","author":"","url":"https://laredolaw.ca/"},{"text":"Lisa Laredo and her team have been an incredible support to me during the handling of both of my parents'' estates. Lisa is not only highly knowledgeable and efficient, but she also brings a level of compassion and understanding that makes a difficult process much easier to navigate.","author":"","url":"https://laredolaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'laredo-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank you, Tatiana, you helped us a great deal. Tatiana provided a consultation and drafted a letter to the immigration service (my husband and I had never seen such professionally written letters). That determined the outcome, and the matter was resolved in our favour. Thank you!","author":"","url":"https://lawpoint.ca/"},{"text":"Tatiana at LawPoint helped me after my immigration case was refused. She explained everything clearly, created a solid plan, and guided me through the process. Thanks to her hard work, we won the case! I highly recommend Tatiana for immigration helpâshe really knows what she''s doing.","author":"","url":"https://lawpoint.ca/"},{"text":"Tatiana is highly knowledgeable and professional. She was able to answer all our questions and made the entire immigration process much clearer and easier to navigate. Her guidance was truly invaluable.","author":"","url":"https://lawpoint.ca/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'lawpoint-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Megha is incredibly knowledgeable, reliable, thorough, and assertive in her practice. While being objective, she has also shown empathy to us when it was needed. She very articulate and presents herself very well. Highly recommend.","author":"","url":"https://lawsnbeyond.com/"},{"text":"I want to express my sincere gratitude to Farah Razi. She was always supportive every step of the way. Despite the language barrier, she was incredibly patient with me and made sure I understood everything clearly.","author":"","url":"https://lawsnbeyond.com/"},{"text":"Megha Sharma is an excellent lawyer. Very knowledgeable and professional with a great insight, focus on delivery, timely and honest communication. All along, she provided me with the right advice, realistic expectations, and promised service. Thanks Megha!","author":"","url":"https://lawsnbeyond.com/"}]')), updated_at = datetime('now') WHERE slug = 'laws-and-beyond-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Un gros merci à toute l''équipe de m''avoir accompagné dans cette mésaventure. Votre écoute et disponibilité fu remarquable. Vous avez eu un travail colossal que vous avez relevé avec brio que maintenant me permets de pouvoir tourner la page et de vivre sainement.","author":"","url":"https://www.lecabinetm.com/"},{"text":"Service magnifique. Je fais affaire avec vous depuis Avril 2021 pour un dossier contre ivac. Sans votre travail j''aurais déjà abandonné. Avec votre connaissance et votre cœur les choses vont loin et tres bien. Se battre contre un système en faveur d''eux même au lieu des victimes est tout un combat! Tout sera bientôt réglé merci a vous.","author":"","url":"https://www.lecabinetm.com/"},{"text":"Service impeccable et professionnel. Je suis plus que satisfaite par les services du Cabinet M. Je ferais encore affaire avec eux au besoin, sans hésitation.","author":"","url":"https://www.lecabinetm.com/"}]')), updated_at = datetime('now') WHERE slug = 'le-cabinet-m-saint-jerome' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We were first introduced to League and Williams when our boat (our summer family home) was destroyed. Our insurance company declined our claim leaving us emotionally and financially devastated. Darren Williams critically analyzed our circumstances and his tenacious efforts resulted in us receiving our full insurance payout. Thank you to Darren and the awesome League and Williams team.","author":"","url":"https://www.leaguelaw.com/"},{"text":"I was recently represented by Andrew Broadley in an injury accident claim. The service I received from Andrew and League and Williams staff Taryn Smith and Wendy Ferrara was at all times nothing short of exemplary. I felt throughout the whole process that my health and recovery were the foremost consideration.","author":"","url":"https://www.leaguelaw.com/"},{"text":"Don handled my late husband’s estate in a highly efficient manner. Also he always made me feel valued and I experienced peace of mind knowing that matters were in his hands. I have much appreciation for what he has done for me. Susan Dubois","author":"","url":"https://www.leaguelaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'league-and-williams-lawyers-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I highly recommend Nathan. He was professional, knowledgeable, approachable and incredibly supportive throughout the entire process. He took the time to explain things clearly, answer my questions and ensure I felt informed and confident every step of the way. His guidance, patience and genuine compassion made a difficult process much easier to navigate. I truly appreciated his dedication and advocacy.","author":"Kelsie R.","url":"https://leckerslaw.com/"},{"text":"I cannot recommend Lecker & Associates highly enough. I had the pleasure of dealing with Jon, who was absolutely exceptional. The staff is general were incredibly kind, professional, compassionate, and understanding throughout my interactions with them. What truly stood out was the genuine care, patience, and respect they demonstrated.","author":"Marni S.","url":"https://leckerslaw.com/"},{"text":"Want to personally thankMatthew and Eslita and Lecker and Associates who listened to my concerns and hep me find a resolution that I was happy with in a timely matter. Thank you again Matthew and Eslita!","author":"Drew L.","url":"https://leckerslaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'lecker-and-associates-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I retained Lee & Company to help my family’s former live-in caregiver to sponsor her children’s permanent residency applications from the Philippines. Winnie Lee and her team are the consummate immigration professionals and will do their absolute best to achieve the greatest possible results for their clients. The children of my former caregiver are here in Canada now, and they...","author":"","url":"https://leecompany.ca/testimonials-peers/"},{"text":"Miss Lee is a very dedicated and efficient lawyer. When I met her for the first time, I had a deportation case where a family of our church had only 48 hours time frame to leave Canada. Miss Lee had to work through the night in order to have the appeal ready in the morning for submission. Miss Lee fought...","author":"","url":"https://leecompany.ca/testimonials-peers/"},{"text":"I am very well connected in the South Asian community and I know that Lee & Company has a wonderful reputation in our community. They have worked on many, many cases and achieved remarkable results. I have seen them win appeals and re-unite families; win judicial reviews and bring deserving and grateful foreign nationals to join our Canadian community. They...","author":"","url":"https://leecompany.ca/testimonials-peers/"}]')), updated_at = datetime('now') WHERE slug = 'lee-and-company-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Had a wonderful experience with Mary and Lisa for the sale of our house. Highly recommend them!","author":"","url":"https://legalfocus.ca/"},{"text":"We have been working with Lisa and her team for a year, and their efficiency, workflow, communication and their professionalism has made it an incredible experience. Hire them!","author":"","url":"https://legalfocus.ca/"},{"text":"Legal Focus was an incredible help in my home buying experience! Lisa took such care and went over everything in great detail with kindness and patience to ensure I felt comfortable and had an understanding. I would absolutely recommend Legal Focus!","author":"","url":"https://legalfocus.ca/"}]')), updated_at = datetime('now') WHERE slug = 'legal-focus-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had a very positive experience with Legal Solutions Law Firm. Ryan represented me in a family court matter and provided excellent guidance and support throughout the entire process. He was professional, knowledgeable, and always took the time to answer my questions and explain everything clearly.","author":"","url":"https://legalsolutionslawfirm.ca/"},{"text":"We tried to defend ourselves in civil court, but ultimately decided to hire Ryan — and it was the wisest decision we have made in the last two years of hell with our condo managers.","author":"","url":"https://legalsolutionslawfirm.ca/"},{"text":"Ryan did an outstanding job on my case. He was clear, professional, and always kept me informed. Thanks to his hard work, my charges were dropped. I’m very grateful and highly recommend him.","author":"","url":"https://legalsolutionslawfirm.ca/"}]')), updated_at = datetime('now') WHERE slug = 'legal-solutions-law-firm-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
