UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Je suis très satisfaite du service professionnel et personnalisé que j’ai reçu. Ils m’ont enlevé un très gros poids sur les épaules qui pesait lourd depuis beaucoup trop longtemps. Ils m’ont accompagné étroitement, étape par étape afin de bien répondre à mon besoin et j’en suis heureuse aujourd’hui. Merci ! Nadia Coriveau","author":"","url":"https://roysyndic.ca/"},{"text":"Je suis vraiment contente de vous avoir rencontrée, ce fut une rencontre très professionnelle et j’ai grandement apprécié votre diplomatie et votre façon d’expliquer ce genre de situation, ainsi que tous les formulaires à signer.Je me suis sentie à l’aise au cours de notre rencontre, je n’ai ressentie aucun jugement de votre part et c’était très important pour moi, car…","author":"","url":"https://roysyndic.ca/"},{"text":"Ça été formidable, vous êtes une bonne équipe. Vous m’avez mie en confiance, c’est pas évident pour moi de retourner dans une autre faillite. Merci beaucoup pour tout. Jules Langlois","author":"","url":"https://roysyndic.ca/"}]')), updated_at = datetime('now') WHERE slug = 'm-roy-and-associes-drummondville' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
