UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Malina Roshan revived my faith in lawyers and the legal system. She is extremely knowledgeable, well organized and always communicated in detail of current status even after regular business hours to put my mind at ease.","author":"","url":"https://roshanlaw.com/"},{"text":"Malina saved my life. In 2018 I was going through an acrimonious divorce. At that time my ex hired an aggressive bay street law firm and I hired a local law firm. For the next three months I watched her bay street lawyers bully my lawyer and force unreasonable concessions from her.","author":"","url":"https://roshanlaw.com/"},{"text":"I had the pleasure of working with Malina Roshan and her team during a challenging time, and I couldn''t be more grateful for her professionalism, expertise, and support. From the very beginning, she was very attentive to my needs, explained the legal process clearly, and provided sound advice that helped me make informed decisions.","author":"","url":"https://roshanlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'malina-a-roshan-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Manbir Singh Sodhi was there when I needed him the most. He even came to the police station to be present during my questioning and helped protect my rights. Mr. Sodhi took the time to explain the possible outcomes for my criminal offences and best case scenario, so I knew upfront what to expect without any unrealistic expectations.","author":"","url":"https://www.manbirsodhilaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'manbir-sodhi-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Austin helped me sort out my work permit and I wanted to share how it went. I had been stuck for a while trying to understand what documents were actually needed. During the meeting he went through everything with me and pointed out what needed attention.","author":"","url":"https://mandallimmigrationlaw.com/"},{"text":"I booked a meeting to ask about applying for a PGWP after finishing my program. The lawyer answered my questions and gave me clear direction on what was required. The appointment went smoothly and I got the information I needed to continue. I’m satisfied with the help I received","author":"","url":"https://mandallimmigrationlaw.com/"},{"text":"I came here for my visitor visa extension and the staff were very polite with me. They explained things slowly and made the steps easier for me to understand. I asked many questions and they always responded without any problem. I’m thankful for the help they provided.","author":"","url":"https://mandallimmigrationlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'mandall-immigration-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"⭐⭐⭐⭐⭐ I had the best experience working with Mandeep Saggi. He is not only knowledgeable and professional but also genuinely cares about his clients. He helped me through one of the most stressful times in my life and successfully got my charges withdrawn. His confidence, communication, and dedication gave me peace of mind throughout the entire process.","author":"","url":"https://saggilawfirm.com/"},{"text":"His expertise and dedication were evident throughout the process, and he was always available to answer my questions and address my concerns. Thank you so much Mr. Mandeep Saggi","author":"","url":"https://saggilawfirm.com/"},{"text":"He’s not just a lawyer, he’s a scientist of law. Mandeep Saggi has the rare ability to turn the impossible into possible. If you want results 100% in your favour, he’s the only choice. Calm, positive, and deeply understanding of your family situation and emotions, he offers honest and truly helpful advice.","author":"","url":"https://saggilawfirm.com/"}]')), updated_at = datetime('now') WHERE slug = 'mandeep-saggi-criminal-lawyer' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
