UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"What I appreciated most about working with Cedric was his excellent communication, he was always available to answer questions and consistently kept me updated.","author":"","url":"https://www.marinimmigrationlaw.ca/claim-citizenship-by-descent"},{"text":"She spent extra time to answer my questions and afterward sent me email follow-up with helpful links to assist me in finding elusive documents.","author":"","url":"https://www.marinimmigrationlaw.ca/claim-citizenship-by-descent"},{"text":"He was able to give me a huge amount of info in a short period of time, as well as clear recommendations and next steps for my situation. … This was super helpful and well worth the cost.","author":"","url":"https://www.marinimmigrationlaw.ca/claim-citizenship-by-descent"}]')), updated_at = datetime('now') WHERE slug = 'marin-immigration-law-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
