UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Natalia conducted herself in an utmost professional manner and clearly explained the final steps in the process I had a positive experience and will recommend to my family and friends. thank you for all your hard work!","author":"","url":"https://svechinlaw.ca/"},{"text":"I highly recommend Natalia Svechin to anyone applying for an immigration. She was a tremendous help for us, she is highly professional and reliable. She made the process so smooth and achievable. We could not have done it without Natalia’s help in such tight deadlines.","author":"","url":"https://svechinlaw.ca/"},{"text":"I highly recommend Natalia as the really strong professional in Immigration law. Personally she calm and confident, and this calmness based on her great experience and knowledge. As a client I had a million of questions and remarks but always got the right and true answers.","author":"","url":"https://svechinlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'natalia-svechin-law-corporation-winnipeg' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I highly recommend working with Ken for family law matters. His entire team is professional, punctual, and incredibly kind. Ken''s grounded advice is always backed by sound experience, knowledge and skill, making me feel supported and confident throughout. I''m truly grateful for my experience.","author":"","url":"https://www.nathenssiegel.com/"},{"text":"Brahm handled my case with great professionalism, always prioritizing my best interests while working toward a fair settlement. Divorce is never an easy process, but with Brahm’s guidance, I felt I was in good hands every step of the way. He made the journey as smooth as possible, and I truly appreciate his dedication and expertise. I highly recommend him.","author":"","url":"https://www.nathenssiegel.com/"}]')), updated_at = datetime('now') WHERE slug = 'nathens-siegel-llp-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
