UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I’m extremely grateful for the representation I received. The charges against me were dropped at the very first hearing. Everything was handled professionally, efficiently, and with great attention to detail. Highly recommend.","author":"","url":"https://nirwallaw.com/"},{"text":"Manbir is an amazing lawyer! He helped my friend with a criminal case and got it withdrawn right in the first pre-trial. Super professional and easy to talk to. If you ever need a good defence lawyer, he’s the one to call!","author":"","url":"https://nirwallaw.com/"},{"text":"Truly Impressive Lawyer! My relative had a criminal case, and we were all very stressed about it. We contacted Manbir Nirwal, and he handled everything better than we expected. In the very first pre-trial meeting, he was able to get the case completely withdrawn, no peace bond or fees required.","author":"","url":"https://nirwallaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'nirwal-law-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
