UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"The team at One Family Law was excellent throughout the entire process. They were friendly, thorough, and efficient. I was very happy that this service and team exists, and that they were available to guide us through our amicable divorce.","author":"","url":"https://www.onefamily.law/"},{"text":"Excellent, excellent office! So lucky to have come across them, saved us so much money, so much unnecessary acrimony and anguish, recommend it to anyone who must turn a new leaf and is not quarrelsome, small-minded, vindictive, and petty. Have recommended it already, in fact, and will do again, any time a chance presents itself.","author":"","url":"https://www.onefamily.law/"},{"text":"My experience with One Family Law was positive throughout the process. Melissa kept us on track, focusing on the important, necessary steps, making the best out of an uncomfortable situation. Our divorce was finalized within 5 months of starting the process. All support staff were amazing and patient with my many questions as well.","author":"","url":"https://www.onefamily.law/"}]')), updated_at = datetime('now') WHERE slug = 'one-family-law-edmonton-divorce-law-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I was referred to Louisa Ledesma at Onyx Law Group for assistance with questions regarding family law, and I am incredibly grateful for that referral. From the very beginning, Louisa made me feel heard, supported, and understood. She is truly a gem—highly capable, professional, personable, and genuinely empathetic.","author":"Cheryl M.","url":"https://onyxlaw.ca/"},{"text":"We worked with Jesse Patrao at Onyx Law Group during a long and complicated jointly owned property matter involving a POA. We aren’t local, but Jesse ensured everything could be handled remotely and made the process as smooth as possible. Throughout an almost 2-year matter, Jesse remained calm, professional, thorough, and responsive.","author":"Steph B.","url":"https://onyxlaw.ca/"},{"text":"I can''t thank Onyx Law group and specifically Louisa Ledesma to prepare and finalize my desk order divorce.","author":"","url":"https://onyxlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'onyx-law-group-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Diversity and inclusion is at the core of our firm’s mission and strategy. We walk the talk when it comes to diversity and multiculturalism. Also, effective communication is the key to our success.","author":"","url":"https://osujismith.ca/"},{"text":"Charles was fantastic to work with! He was very professional, made sure I knew my options and supportive to the end. He successfully handled my employment matter and I would hire Charles again if needed.","author":"","url":"https://osujismith.ca/testimonial/"},{"text":"Aniedi Davidson at Osuji & Smith made our experience of incorporating interesting, accessible and hassle free. She took the time required to help us understand the process thoroughly and was very kind and friendly. Incorporating felt like a large task to us and she made it easy! I would highly recommend her services to anyone looking to incorporate their business.","author":"","url":"https://osujismith.ca/testimonial/"}]')), updated_at = datetime('now') WHERE slug = 'osuji-and-smith-employment-lawyers-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Ehsan Zebian Pace Law Firm, Mr. Kram team where my representatives. I will forever pass there name to anyone that is looking for legal advice or needs. I am very happy with my settlement awarded. Brume, Martha & Mr. Kram, Sanaa where awesome. Anyone reading this review this is yoir sign to stop looking for legal representation.","author":"Ehsan Z.","url":"https://pacelawfirm.com/testimonials/"},{"text":"Animal and Nahman have been very helpful and followed through and listen to their clients and customers they have listened and supported me very well.","author":"Bryce G.","url":"https://pacelawfirm.com/testimonials/"},{"text":"I am very satisfied with chowbay law firm and specifically for tayannah she did wonderful work for my claim and got my income replacement benefits approved. She is a fighter! I got my settlement offer which is over my expectations billions of thanks to chowbay and her team. Tyannah communicated with me every documents and val is a wonderful professional.","author":"Mehwish K.","url":"https://pacelawfirm.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'pace-law-firm' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I truly recommend Paciocco & Mellow law firm. I would like to thank Dina D''Andrea and associates for all their hard work on my court case. I will definitely use their service in the future if needed. Thank you again Mike K","author":"","url":"https://accidentlawyerswindsor.com/"},{"text":"My accident case involved multiple insurance defendants, one of whom did not have insurance. The office of Paciocco & Mellow not only took on my case, they addressed any issues I had with my own Insurance Adjuster throughout my recovery. They were in contact with me with each relevant step up to Mediation.","author":"","url":"https://accidentlawyerswindsor.com/"},{"text":"Gino and his team of associates did a wonderful job of making sure all our needs and concerns were taken care of. We would highly recommend their services!","author":"","url":"https://accidentlawyerswindsor.com/"}]')), updated_at = datetime('now') WHERE slug = 'paciocco-and-mellow-windsor' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Sometimes you ask the seemingly impossible. And this team pulled it off. I returned from Asia with no place to live and needed a new home ASAP. I found a place on the Oct 29th and made an offer on Nov 2. Which was accepted. I removed all conditions soon after but asked for a closing date of Nov. 6th.","author":"D M.","url":"https://pactumlaw.ca/"},{"text":"I worked with Beverly Duong to sell the townhouse. She is professional who made the process easy and efficient. I would definitely recommend Beverly Duong for the service.","author":"","url":"https://pactumlaw.ca/"},{"text":"I had a great experience with Beverly Duong. I used her services once and was very happy, so I came back to her again. She is honest, professional, kind, and always quick to respond. I highly recommend her to anyone looking for a trustworthy lawyer.","author":"","url":"https://pactumlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'pactum-law-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank you Sam and team for helping us close on our home back in November. You guys helped us closed even with our tight deadline. Highly recommended","author":"","url":"https://www.parlatorelawyers.com/"},{"text":"Excellent service very knowledgeable and helpful. Thank you for your expertise and I appreciate your help.","author":"","url":"https://www.parlatorelawyers.com/"},{"text":"If you’re looking for a lawyer that is trustworthy, kind and caring, call Sam. He and his team helped my family navigate a legal matter during a very difficult time. He went above and beyond and we are truly grateful. You’re in great hands with Parlatore Law.","author":"","url":"https://www.parlatorelawyers.com/"}]')), updated_at = datetime('now') WHERE slug = 'parlatore-law-niagara-niagara-falls' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Rick Patel is an amazing lawyer and an extremely down to earthhuman being. A literal miracle worker. If you want the best possible result in your case I couldn’t recommend Passi and Patel any more. Saved my life from a drug trafficing case with no criminal record. Your paying for perfection when you hire these guys.","author":"","url":"https://passipatel.com/testimonials/"},{"text":"Hello, I am writing this review to express my most sincere gratitude for the most professional representation. Mr. Patel have stood by me through the years in dealing with my stressful case. I admire his composure, work ethic and most of all excellent representation. Mr.","author":"","url":"https://passipatel.com/testimonials/"},{"text":"Thank you so much for advice you given me last week over the phone. You saved me a lot of money. Mark Kowal — Feb, 2024","author":"","url":"https://passipatel.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'passi-patel' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Our job is to guide you through the journey of your divorce with clarity, compassion, and a proven approach that’s focused on the solutions, not the conflict","author":"","url":"https://www.pathwaylegal.ca/"},{"text":"The Pathway Legal Family Lawyers'' priority is to reduce the emotional and financial stress of divorce by offering compassionate and personalized support. We are committed to working collaboratively to find the best solutions for our clients and their families, helping them avoid the expense and emotional strain of litigation whenever possible.","author":"","url":"https://www.pathwaylegal.ca/about-pathway-legal.html#googlereviews"}]')), updated_at = datetime('now') WHERE slug = 'pathway-legal-family-lawyers' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Where do I begin?! I am truly grateful to this wonderful woman that became a saviour to all clients that needed a lawyer they can count on. I will always be thankful for the help and support this law firm did for me! If anyone is looking for a blessing it’s this law firm.","author":"","url":"https://patriciabrownlawyer.com/"},{"text":"Thank you patricia its being years now and i still remember how you fought for me thank you from the bottom of my heart","author":"","url":"https://patriciabrownlawyer.com/"},{"text":"Patricia Brown and her team procured the best outcome possible for my specific issue. I am very grateful for her and her team for the care that they took in taking me through a process in a time I never thought I would ever be in. I happily would recommend her to anyone in need of a defense lawyer","author":"","url":"https://patriciabrownlawyer.com/"}]')), updated_at = datetime('now') WHERE slug = 'patricia-brown-barrister-and-solicitor-windsor' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
