UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We’ve done 3 house transactions with Ken and all have been excellent. Ken and his team is a joy to work with through all the details and stresses of buying/selling a home. We would recommend him over and over again","author":"","url":"https://www.pazderlaw.com/post/testimonials"},{"text":"On our last transaction, my wife went into labor before we could get into the office and meet with the Pazder group to sign the necessary documents. As a deadline was fast approaching, Kenneth made an after-hours, late night visit to the hospital in order to ensure the transaction would be completed.","author":"","url":"https://www.pazderlaw.com/post/testimonials"},{"text":"Great experience with Ken. I highly recommend his services, he gave me the confidence to sell my property without a realtor, I save a lot of money thanks to him, not a thing you can often say about lawyers. He was available at 9 PM when I got an offer with a deadline of midnight the same day.","author":"","url":"https://www.pazderlaw.com/post/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'pazder-law-corporation-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
