UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank You! Mr. Lindsay! You’re the best! Honestly, I don’t want to see you as your “court client” again! I will drive extremely careful from now on and will definitely refer you to those who need your professional service!","author":"","url":"https://www.lindsaylaw.ca/"},{"text":"Thank you for all the help. I don’t know what to say now (on being informed that the charge against him was withdrawn). This is great news for me. Thank you! Thank you! Thank you!","author":"","url":"https://www.lindsaylaw.ca/"},{"text":"非常感谢你们帮我打掉这个案子！非常感谢Peter律师 这两天在庭上的出色表现！今后如果需要你们还会找你们 身边朋友如有需要也会极力推荐你们！感谢！ (Translation: Thank you very much for your help in dropping my charges. I very much appreciate counsel Peter for his brilliant performance those 2 days in court. In the future, if needed, I will still come back to you. If I have friends who need help, I will highly recommend you guys. Thank you!)","author":"","url":"https://www.lindsaylaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'peter-robert-lindsay-professional-corporation-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
