UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Samantha Ramsarran Ziv, has been amazing through this entire process! He is professional, and always available! He takes the time and goes above and beyond for his clients! I cannot thank him enough for putting me first and truly caring about the situation and making sure I was properly compensated.","author":"","url":"https://ptlawyers.ca/who-we-are/"},{"text":"Ethan Hunt Great people, you will not feel that you are alone. All through out they are there. Nice knowing you guys specially Philip very professional. On another level, Philip is very assertive, diligent and a strong negotiator in his approach with the insurance companies! He was caring with me but tough with them.","author":"","url":"https://ptlawyers.ca/who-we-are/"},{"text":"Maggie Dias I’m really glad I went with this legal firm. Phillip was fantastic in so many ways! He was attentive and explained the process/fee’s very clearly. Throughout this whole process – Philip was always honest, transparent and responsive, regularly providing updates on the case as his communications with the other parties.","author":"","url":"https://ptlawyers.ca/who-we-are/"}]')), updated_at = datetime('now') WHERE slug = 'pollack-tsimerman-llp-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
