UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Stuart Rudner was recommended to me and I have to say that I’m grateful he was! He helped me navigate through a difficult situation at work and the outcome was positive. It’s a great feeling knowing that you have someone like Stuart in your corner when times are tough. I would most definitely recommend Stuart Rudner and his wonderful staff!","author":"","url":"https://www.rudnerlaw.ca/"},{"text":"I have known Stuart for many years and when it came time to redo our employment agreements, he was my only call. He changed our simple 2 page contract to a detailed agreement that protects us and our employees and removed any doubt about our responsibilities under the current laws.","author":"","url":"https://www.rudnerlaw.ca/"},{"text":"Stuart, I was very impressed with your approach and results at the mediation last week. My client sent a very positive message to Tiffany and I wanted to thank you for your professionalism, humour and wisdom. I look forward to working together in the future.","author":"","url":"https://www.rudnerlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'rudner-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
