UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I retained Irin Sidhu at this law firm in hopes of resolving my family matter quickly. He conducted himself professional, and a reliable, trusted source for family law matters.\" G. Rose, BC","author":"","url":"https://www.silawgroup.ca/testimonials"},{"text":"I am very grateful to SiLaw Group firm especially Mr.Pritesh Pachchigar for all his services and support. He is very compassionate, professional lawyer, great negotiator and works towards the resolution of the case in a timely and effective manner.\" A. C., BC","author":"","url":"https://www.silawgroup.ca/testimonials"},{"text":"i will highly recommend SANDY SIHOTA for all family case and kids matters. Thanks sandy for all your help and support\" J. Singh, BC","author":"","url":"https://www.silawgroup.ca/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'silaw-group-family-lawyers-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Needing to make a TN visa on a short schedule, I got excellent service and a successful application on a very tight schedule, with excellent and fast communication at every step - highly recommended.","author":"","url":"https://silverimmigration.com/en/"},{"text":"Hands down, the real deal. Matt was honest, straightforward, and knew exactly what needed to be done. His assistant, Emma, was kind, knowledgeable, responsive, and incredibly helpful throughout every stage of my visa process. I appreciate people who are direct, transparent, and truly know their craft, and that is exactly what I found with Matt and his team.","author":"","url":"https://silverimmigration.com/en/"},{"text":"Matthew and Emma were amazing to work with. They were professional, efficient, and incredibly supportive throughout my immigration process. Everything was handled smoothly and I felt confident every step of the way. Highly recommend!","author":"","url":"https://silverimmigration.com/en/"}]')), updated_at = datetime('now') WHERE slug = 'silver-immigration-montreal' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
