UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I just want to say thanks to Eric. From the first phone call I was well informed and respected. I am very glad I trusted Eric’s legal advice as it ultimately led to N outcome that was so much better than I had hoped for. Highly recommend him to anyone needing a lawyer for family law matters. Kingsley Sim","author":"","url":"https://tczlaw.ca/testimonial/"},{"text":"Eric came to my rescue when I felt like I was drowning...He represented my matters in literally 1 day notice and made sure I get favorable outcomes all through. He always gave me practical advice and helped me resolve the issues through mediation or conference.","author":"","url":"https://tczlaw.ca/testimonial/"},{"text":"Lawyer Zhao is a very responsible lawyer. Whenever I have questions, I can call him and he''ll explain them to me. This makes me feel safe while living in a foreign country. He''s very efficient. I''m lucky to have met him while I''m abroad. Yumei Xiao","author":"","url":"https://tczlaw.ca/testimonial/"}]')), updated_at = datetime('now') WHERE slug = 'tcz-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Sarah has done great work on our matter. She is a great listener who really understood what we needed. She also got great results. I am recommending Sarah to everyone I know. Former Client","author":"","url":"https://thelawportal.ca/"},{"text":"Sarah was extremely caring when I was going through a very difficult time. I felt that she represented me well while also keeping my legal bills within my means. I highly recommend Sarah if you’re looking for a compassionate and trustworthy divorce lawyer. Former Client","author":"","url":"https://thelawportal.ca/"},{"text":"I needed some complicated legal advice and I was so pleased to be put in contact with Sarah. She already came highly recommended. She was able to answer all my questions in a way I could understand as a lay person. She did not use unnecessary legal language. This was extremely helpful. Sarah was very down to earth.","author":"","url":"https://thelawportal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'the-law-portal-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I highly recommend The Legal Pillars for your legal needs. Mr. Angad Singh have been extremely helpful to my family. They went above and beyond to provide us with valuable information in a timely manner when we needed their guidance the most. We truly appreciate him and highly recommend him.","author":"","url":"https://thelegalpillars.com/"},{"text":"I would recommend this Law Firm 11 out of 10. They truly care for your best interests. They worked hard and diligently on my case and I’m sure they would for everyone’s case. Do not hesitate to call The Legal Pillars team!!! They’re the best!!","author":"","url":"https://thelegalpillars.com/"},{"text":"Very impressed with the service we received for our property closing from The Legal Pillars team and lawyer Angad Singh. After closing, he followed up to make sure everything was fine, and we got our legal package with all signed documents a few days later. Angad Singh and The Legal Pillars provide professional service.","author":"","url":"https://thelegalpillars.com/"}]')), updated_at = datetime('now') WHERE slug = 'the-legal-pillars-pc-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"As a current client of the Riley Law Office I can attest to his and the entire team''s professionalism, efficiency, and compassion in dealing with a persons'' legal matters. Mr. Riley has been upfront, extensively available to walk me through the legal process, and has taken the time to understand and seek resolution on my unique concerns.","author":"J.W","url":"https://www.therileyfirm.ca/testimonial-page/"},{"text":"Paul, Liz and the whole Riley firm have been supporting me over the past two years with a very difficult family law situation.","author":"","url":"https://www.therileyfirm.ca/testimonial-page/"},{"text":"I contacted Paul during one of the roughest periods of my life. Paul showed me compassion and understanding. He also treated me with respect; and assured me that all will be well.","author":"A. E.","url":"https://www.therileyfirm.ca/testimonial-page/"}]')), updated_at = datetime('now') WHERE slug = 'the-riley-divorce-and-family-law-firm' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Clients come to us for clarity and leave with advice they can trust. Jaskaran Sandhu Managing Partner","author":"","url":"https://tidallaw.ca/"},{"text":"Guntash is the kind of lawyer you want in your corner. She is knowledgeable, responsive, and truly takes the time to ensure you understand every step of the process. Her professionalism and attention to detail gave me confidence from start to finish. I highly recommend her to anyone seeking a family lawyer!","author":"","url":"https://tidallaw.ca/"},{"text":"Choosing Guntash Gill was one of the best decisions we made. From day one, she was organized, clear, and always on top of everything. She took the time to explain our options, answered questions honestly, and made sure we felt confident throughout the process. It’s rare to find someone who is both highly competent and genuinely invested in her clients.","author":"","url":"https://tidallaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'tidal-law-llp-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
