UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Justicejolt’s level of services was excellent. The team is very responsive, took the time and effort to take me through all possible outcomes, and their probabilities. Most importantly, they are effective, and were successful in getting my speeding charges dropped!” – Chandan Meh (Mississauga)","author":"","url":"https://www.justicejolt.com/"},{"text":"Justice jolt were incredibly professional..and the price was right..they made me feel very assured..justice jolt got me off everything..I was charged with stunt driving at 133kmh in a 80 zone (passing lane )..I am so happy with them thank you Justice jolt” – Brian Allen (Belleville)","author":"","url":"https://www.justicejolt.com/"},{"text":"Speeding 146km/h in a posted 100km/h zone” – WITHDRAWN. Wow. Out-f’n-Standing. First good news I’ve had in some time. Thank you Mike, and to anyone else involved.” – Edward O’Brien (Toronto)","author":"","url":"https://www.justicejolt.com/"}]')), updated_at = datetime('now') WHERE slug = 'traffic-tickets-toronto-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
