UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Highly recommended! All details were explained in a professional manner to me, and my lawyer handled my case excellently!","author":"","url":"https://www.yeungassociates.com/"},{"text":"My mom had an excellent experience working with them. She felt well-supported and confident throughout. Their expertise and dedication truly stood out, and I’m very grateful for their help. Highly recommended!!!","author":"","url":"https://www.yeungassociates.com/"},{"text":"Very professional, close my case successfully. I recommend Yeung & Associates Law Professional to everyone.","author":"","url":"https://www.yeungassociates.com/"}]')), updated_at = datetime('now') WHERE slug = 'yeung-and-associates-law-professional-corporation-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"There are many things that separate YLaw from other law firms, but one of them I truly valued as their client was everyone involved caring about my case. This is not just a law firm but a group of lawyers that go above and beyond for you with great dedication and skill. I totally recommend them.","author":"","url":"https://www.ylaw.ca/"},{"text":"I retained Justin as my lawyer and Laura is his assistant. I am so impressed by their professional, honest, communication and especially dedication and empathy. Justin works very hard and very efficiently on my case. When he was assigned a task he worked on it right away and he replied to me the next day!","author":"","url":"https://www.ylaw.ca/about/law-firm-testimonials/"},{"text":"Raman Sehmbi and her team were very helpful in providing me with legal advice and services. She is very caring and an excellent communicator. I would recommend her as an attorney who is easy to deal with and provides great service. -","author":"","url":"https://www.ylaw.ca/about/law-firm-testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'ylaw-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Where do I start. The professionalism, commitment and dedication of Martin is impeccable. These are the kind of lawyers we need here in Canada. He upholds the standards and ensures he provides the right direction to his clients. I want to publicly thank you Martin for helping me through my litigation process. Work with Martin and you won’t regret it.","author":"","url":"https://zlegal.ca/"},{"text":"Martin was professional… very informative… personable & answered all my questions.He was candid about the accuracy of his response which enabled me to feel confident about making the right decision. Thank you Martin for your candour.","author":"","url":"https://zlegal.ca/"},{"text":"I found Martin’s firm on internet several years ago when my husband needed Employment Law Lawyer.","author":"","url":"https://zlegal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'z-legal-litigation-lawyer-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Working with Luke Zacharias, and his paralegal Lorri Luxford was an excellent experience. They were patient, kind, and always took the time to answer my questions. I never felt rushed or overlooked. Their professionalism and dedication gave me complete confidence throughout my case. I’m very grateful for their support and would recommend them without hesitation.","author":"","url":"https://zmllp.ca/?utm_source=GBP&utm_medium=GBP&utm_campaign=GBP_Abbotsford&utm_id=GBP_Abbotsford"},{"text":"I had a great experience working with Zacharias Vickers McCann LLP. The team was professional, efficient, and made the entire process smooth and stress-free. A special thank you to Lorri Luxford — she was very kind, helpful, and always took the time to explain things clearly. I really appreciated her support and guidance throughout.","author":"","url":"https://zmllp.ca/?utm_source=GBP&utm_medium=GBP&utm_campaign=GBP_Abbotsford&utm_id=GBP_Abbotsford"}]')), updated_at = datetime('now') WHERE slug = 'zacharias-mccann-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am absolutely convinced that these criminal lawyers are the best in the GTA I had the best experience with them in terms of professionalism and honesty from the jump all.","author":"","url":"https://zamani-law.com/"},{"text":"I called Mr. Zamani not knowing what to do. Never having been in a situation like this before I was terrified. A family member needed my help and I needed his help. Mr. Zamani put me at ease with the first conversation. His is extremely professional, compassionate and knowledgeable. He was in constant contact with updates to help ease anxiety.","author":"","url":"https://zamani-law.com/bails-reviews/"}]')), updated_at = datetime('now') WHERE slug = 'zamani-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Zemp Law Group did a remarkable job getting my Permanent Residence Application approval. They found an error on the application I submitted by myself, they fixed it, submitted it again and I got my PR approval. They’re very professional, knowledgable and efficient. Thank you!","author":"","url":"https://www.zemplaw.com/"},{"text":"I received help with obtaining my immigration document from Matthew Lebaron and Kevin Zemp. They were both professional, personable, and responsive. They walked me through each step and their strategy/advice led to a very positive result for me. If you need assistance with immigrating to Canada, I highly recommend them.","author":"","url":"https://www.zemplaw.com/"},{"text":"I’m so grateful for the service they gave us, they have great communication, and helped us with my husbands PR application, and we couldn’t have done it without them","author":"","url":"https://www.zemplaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'zemp-law-group-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Zoe has been a great help when it comes to employment matters. From the moment I reached out, she was attentive, understanding, and incredibly knowledgeable. She took the time to really listen to my concerns and provided clear, practical advice that helped me better understand the situation I was facing.","author":"","url":"https://arghandewal.ca/"},{"text":"I came to Zoe with some paperwork a prospective employer wanted me to sign. Zoe dissected it, pointed out why it was problematic, and translated it from lawyer jargon into plain English. She is passionate, highly intelligent, and was on my side. I''d definitely recommend her for anything employment related.","author":"","url":"https://arghandewal.ca/"},{"text":"Zoe was very knowledgeable and professional, and yet was able to show compassion regarding my issue. She gave me assurance and confidence in how I wanted to proceed. Highly recommend this firm. 5 stars!","author":"","url":"https://arghandewal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'zoe-arghandewal-nanaimo' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Anya and her law firm was wonderful to work with! She was very efficient and knowledgeable and helped me out with a time sensitive situation. I highly recommend Anya!","author":"","url":"https://www.zubiclaw.com/"},{"text":"Anya was amazing in guiding us through legal aspects of the real estate transaction we conducted. The (many) questions we had, some unique to our situation, Anya either answered directly or took away to promptly and effectively get answered by team members in her law firm with relevant subject matter expertise.","author":"","url":"https://www.zubiclaw.com/"},{"text":"As a lawyer in Niagara Falls, Anya has a wealth of experience and expertise in the field, and she consistently goes above and beyond to provide her clients with excellent service. Her attention to detail, strong negotiation skills, and in-depth knowledge of real estate law make her a top choice for any real estate transaction.","author":"","url":"https://www.zubiclaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'zubic-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
